package polski.data

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull
import polski.data.rows.enru.EnSeedRow
import polski.model.SentenceSeed

/**
 * R1.14b: the en-ru pair data from the generated rows (the mappers are the EnRu... copies of the pl-ru ones, generated by dsl/derive-enru-mappers.mjs, whose logic PlRuRowsTest,
 * PlRuVocabularyRowsTest and the other pl-ru tests pin) against values read off the sealed courses/pairs/en-ru/pair.json (sha256 55f79438...) and courses/lang/en/curriculum.json
 * (sha256 4c8f1c21...) before they were transcribed.
 */
class EnRuPairRowsTest {
    @Test fun aSeedIsItsNounAndItsAdjective() {
        assertEquals(listOf(SentenceSeed("wife", "beautiful")), listOf(EnSeedRow("wife", "beautiful")).toSeeds())
    }

    @Test fun theSixteenSkillsComeInTheOrderOfThePairWithTheirLevelsAndPrerequisites() {
        assertEquals(
            listOf(
                Triple("en:role.object", "A1", emptyList()), Triple("en:verb.presentSimple", "A1", emptyList()), Triple("en:possessive.my", "A1", listOf("en:role.object")),
                Triple("en:mood.question", "A1", listOf("en:verb.presentSimple")), Triple("en:role.location", "A1", listOf("en:role.object")),
                Triple("en:role.instrument", "A2", listOf("en:role.object")), Triple("en:polarity.present", "A2", listOf("en:role.object")),
                Triple("en:verb.pastSimple", "A2", listOf("en:verb.presentSimple")), Triple("en:role.recipient", "A2", listOf("en:role.instrument")),
                Triple("en:number.plural", "A2", listOf("en:role.object", "en:possessive.my")), Triple("en:polarity.past", "A2", listOf("en:polarity.present", "en:verb.pastSimple")),
                Triple("en:verb.futureSimple", "A2", listOf("en:verb.pastSimple")), Triple("en:pronouns", "A2", listOf("en:role.instrument", "en:role.location")),
                Triple("en:verb.presentContinuous", "B1", listOf("en:verb.presentSimple")), Triple("en:tense.contrast", "B1", listOf("en:verb.futureSimple", "en:verb.presentContinuous")),
                Triple("en:mixed", "B1", listOf("en:possessive.my", "en:verb.pastSimple")),
            ),
            generatedEnRuSkills.map { Triple(it.id, it.level, it.prerequisites) },
        )
    }

    @Test fun theFirstSkillKeepsItsTextsItsFocusItsMethodsAndItsStyleContent() {
        val skill = generatedEnRuSkills.first()
        assertEquals("Object · без падежа" to "Roles", skill.title to skill.group)
        val presentation = generatedEnRuPresentations.getValue(skill.id)
        assertEquals("my beautiful house" to "my beautiful house", presentation.focusBefore to presentation.focusAfter)
        assertEquals("Сначала определи правило и форму.", presentation.logic.promptLead)
        assertEquals(listOf("I see a book.", "I see a dog."), generatedEnRuStyleContent.getValue(skill.id).examples)
        assertNull(generatedEnRuStyleContent.getValue(skill.id).rule)
        assertEquals(16, generatedEnRuPresentations.size)
        assertEquals(16, generatedEnRuStyleContent.size)
    }

    @Test fun theTwelveSeedsAreThoseOfTheSourceInOrder() {
        assertEquals(
            listOf("wife" to "beautiful", "husband" to "good", "friend" to "good", "son" to "small", "dog" to "good", "cat" to "small", "book" to "new", "car" to "new", "house" to "new", "phone" to "new", "child" to "small", "window" to "new"),
            generatedEnRuSentenceSeeds.map { it.nounId to it.adjectiveId },
        )
    }

    @Test fun theExerciseTextHasItsKeysInTheOrderOfTheSource() {
        assertEquals(73, generatedEnRuExerciseCopy.size)
        assertEquals("Скажи, что видишь названное. Начни с «I see…».", generatedEnRuExerciseCopy.getValue("roleObjPrompt"))
        assertEquals(listOf("roleObjPrompt", "roleObjExplanation", "roleObjReason"), generatedEnRuExerciseCopy.keys.take(3))
        assertEquals(
            mapOf("seenObj" to "I see {obj}.", "verbSentence" to "{subj} {verb}.", "subjectVerb" to "I {verb}.", "roleDrill" to "{start} {target}.", "chainPast" to "I saw {obj}.", "chainNeg" to "I did not see {obj}."),
            generatedEnRuExercisePatterns,
        )
        assertEquals(mapOf("Subj" to "Here is"), generatedEnRuCaseSentencePrefixes)
    }

    @Test fun theVocabularyHasThirtyCardsWithoutRanksAndTheTextsAroundThem() {
        val cards = generatedEnRuVocabularyItems
        assertEquals(30, cards.size)
        assertEquals(VocabularyItem("noun.wife", "wife", "жена", "wife · pl. wives (irregular)", "This is my wife.", "A1", null), cards.first())
        assertEquals("verb.be", cards.last().id)
        // the old generator printed no frequency rank for any card and the rows keep that: the ranks of the source (17 of 30) are not connected to anything yet
        assertEquals(emptyList(), cards.mapNotNull { it.frequencyRank })
        assertEquals("Перевод и пример ещё не проверены", generatedEnRuVocabularyUnavailableLabel)
        assertEquals(true, generatedEnRuVocabularyInstructions.native.startsWith("Частотный ранг не равен уровню CEFR."))
    }

    @Test fun theChainHasTheFiveStepsOfTheSource() {
        val chain = generatedEnRuChainPresentation
        assertEquals(listOf("obj" to "Вижу", "past" to "Прошлое", "neg" to "Отрицание", "owner" to "Владелец", "loc" to "Место"), chain.steps.map { it.id to it.label })
        assertEquals("Цепочка завершена", chain.completion.title)
    }
}
